body.raw:
{
  "query": "query GetMe { me { id email displayName avatarUrl createdAt } }"
}

{
  "query": "query GetWorkspace($id: UUID!) { workspace(id: $id) { id name slug ownerId createdAt } }",
  "variables": { "id": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetProjects($ws: UUID!) { projects(workspaceId: $ws) { nodes { id name description status createdAt } } }",
  "variables": { "ws": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetBoard($id: UUID!) { board(id: $id) { id name projectId createdAt } }",
  "variables": { "id": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetTasks($boardId: UUID!) { tasks(boardId: $boardId) { nodes { id title status priority position dueDate } pageInfo { hasNextPage totalCount } } }",
  "variables": { "boardId": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetTask($id: UUID!) { task(id: $id) { id title description status priority assigneeId createdAt } }",
  "variables": { "id": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetComments($taskId: UUID!) { comments(taskId: $taskId) { id body authorId createdAt } }",
  "variables": { "taskId": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "{ notifications { nodes { id type title readAt createdAt } } unreadNotificationCount { count } }"
}

{
  "query": "query GetActivity($ws: UUID!) { activityFeed(workspaceId: $ws) { nodes { id entityType action createdAt } } }",
  "variables": { "ws": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "query GetDashboard($ws: UUID!) { dashboardSummary(workspaceId: $ws) { taskCountsByStatus urgentOpenCount recentActivity { id action createdAt } } }",
  "variables": { "ws": "00000000-0000-0000-0000-000000000000" }
}

{
  "query": "mutation CreateWorkspace($input: CreateWorkspaceInput!) { createWorkspace(input: $input) { id name slug ownerId } }",
  "variables": {
    "input": { "name": "GraphQL QA Workspace", "slug": "gql-qa-ws" }
  }
}

{
  "query": "mutation CreateTask($input: CreateTaskInput!) { createTask(input: $input) { id title status priority columnId } }",
  "variables": {
    "input": {
      "title": "GraphQL-created task",
      "columnId": "00000000-0000-0000-0000-000000000000",
      "status": "Backlog",
      "priority": 1
    }
  }
}

{
  "query": "mutation AddComment($input: AddCommentInput!) { addComment(input: $input) { id body authorId createdAt } }",
  "variables": {
    "input": {
      "taskId": "00000000-0000-0000-0000-000000000000",
      "body": "Comment posted via GraphQL mutation."
    }
  }
}
